/* R1365 — visible Community Member promotions/events tools */
(()=>{'use strict';
const API='https://franklin-navigator-membership.onrender.com';
const q=(s,r=document)=>r.querySelector(s),qa=(s,r=document)=>[...r.querySelectorAll(s)];
const status=q('[data-r1365-status]');if(!status)return;
const picker=q('[data-r1365-profile-picker]'),editor=q('[data-r1365-editor]'),itemsPanel=q('[data-r1365-items]'),mediaPanel=q('[data-r1365-media]'),form=q('[data-r1365-form]'),mediaForm=q('[data-r1365-media-form]'),list=q('[data-r1365-item-list]'),mediaList=q('[data-r1365-media-list]');
const state={profiles:[],profile:null,items:[],media:[],editing:null,busy:false};
const msg=(text,kind='')=>{status.textContent=text;status.className='r1365-status'+(kind?' '+kind:'')};
async function request(path,{method='GET',body,headers={}}={}){let r;try{r=await fetch(API+path,{method,credentials:'include',cache:'no-store',headers:body?{'Content-Type':'application/json',...headers}:headers,body:body?JSON.stringify(body):undefined})}catch{throw new Error('The member service is temporarily unavailable. Please try again.')}let out={};try{out=await r.json()}catch{}if(!r.ok)throw new Error(out.message||out.error?.message||friendly(out.error||out.code)||'We could not complete that request.');return out}
const friendly=code=>({AUTH_REQUIRED:'Sign in through Member Account to use these tools.',PROFILE_VERIFICATION_REQUIRED:'Verify management access for this profile before using Community Member tools.',ACTIVE_MEMBERSHIP_REQUIRED:'An active Community Membership is required for coupons, promotions, events and promotional graphics.',VERSION_CONFLICT:'This item changed in another session. Reload and try again.',PROMOTION_REVIEW_PENDING:'This item is waiting for review.',MEDIA_REVIEW_PENDING:'This graphic is waiting for review.'}[code]||'');
const toIso=v=>v?new Date(v).toISOString():null;
const toLocal=v=>{if(!v)return'';const d=new Date(v),p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`};
const labelKind=k=>({COUPON:'Coupon',SPECIAL:'Special offer',SALE:'Sale',PROMOTION:'Promotion',EVENT:'Event'}[k]||k);
async function busy(fn){if(state.busy)return;state.busy=true;try{await fn()}catch(e){msg(e.message,'warn')}finally{state.busy=false}}
function setKind(kind){if(!form)return;const select=form.elements.kind;if(select&&['COUPON','SPECIAL','SALE','PROMOTION','EVENT'].includes(kind))select.value=kind;editor.hidden=false;location.hash='promotion-editor';q('[name="title"]',form)?.focus()}
qa('[data-r1365-kind-link]').forEach(a=>a.addEventListener('click',()=>setKind(a.dataset.r1365KindLink)));
async function loadProfiles(){const out=await request('/api/member/profiles');state.profiles=out.profiles||[];picker.replaceChildren();if(!state.profiles.length){msg('No Franklin profile is connected to this account yet.','warn');const a=document.createElement('a');a.href='/profile-access/';a.className='button primary';a.textContent='Find or connect my profile';picker.append(a);return}const label=document.createElement('label');label.textContent='Choose the profile you want to manage';const select=document.createElement('select');select.style.maxWidth='34rem';state.profiles.forEach(p=>{const o=document.createElement('option');o.value=p.profile_id;o.textContent=p.name+(p.authority_state==='VERIFIED'?'':' — access not verified');select.append(o)});label.append(select);picker.append(label);const asked=new URLSearchParams(location.search).get('profile');state.profile=state.profiles.find(p=>p.profile_id===asked)||state.profiles[0];select.value=state.profile.profile_id;select.addEventListener('change',()=>{state.profile=state.profiles.find(p=>p.profile_id===select.value);busy(loadWorkspace)});await loadWorkspace()}
async function loadWorkspace(){if(!state.profile)return;msg('Loading '+state.profile.name+'…');if(state.profile.authority_state!=='VERIFIED'){editor.hidden=itemsPanel.hidden=mediaPanel.hidden=true;msg('Profile access is not verified yet. Complete free profile verification before using member tools.','warn');const a=document.createElement('a');a.href='/profile-studio/?profile='+encodeURIComponent(state.profile.profile_id);a.className='button primary';a.textContent='Complete profile access';picker.append(a);return}try{const [a,b]=await Promise.all([request('/api/member/promotions/list?profileId='+encodeURIComponent(state.profile.profile_id)),request('/api/member/promotions/media/list?profileId='+encodeURIComponent(state.profile.profile_id))]);state.items=a.promotions||[];state.media=b.media||[];editor.hidden=itemsPanel.hidden=mediaPanel.hidden=false;renderItems();renderMedia();msg('Community Member tools are ready for '+state.profile.name+'.','good')}catch(e){editor.hidden=itemsPanel.hidden=mediaPanel.hidden=true;msg(e.message,'warn');if(/active Community Membership/i.test(e.message)){const a=document.createElement('a');a.href='/membership-start/?profile='+encodeURIComponent(state.profile.profile_id);a.className='button primary';a.textContent='Review Community Membership';picker.append(a)}}}
function resetForm(){state.editing=null;form.reset();q('[data-r1365-save]').textContent='Save draft'}
q('[data-r1365-reset]')?.addEventListener('click',resetForm);
form?.addEventListener('submit',e=>{e.preventDefault();busy(async()=>{const d=new FormData(form),payload={kind:d.get('kind'),title:String(d.get('title')||'').trim(),description:String(d.get('description')||'').trim(),promoCode:String(d.get('promoCode')||'').trim(),discountText:String(d.get('discountText')||'').trim(),actionUrl:String(d.get('actionUrl')||'').trim(),startAt:toIso(d.get('startAt')),endAt:toIso(d.get('endAt')),eventLocation:String(d.get('eventLocation')||'').trim()};Object.keys(payload).forEach(k=>{if(payload[k]===''||payload[k]===null)delete payload[k]});if(state.editing){payload.promotionId=state.editing.promotion_id;payload.expectedRevision=state.editing.revision;await request('/api/member/promotions/update?profileId='+encodeURIComponent(state.profile.profile_id),{method:'POST',body:payload});msg('Changes saved as a draft.','good')}else{payload.idempotencyKey='web_'+(crypto.randomUUID?crypto.randomUUID():Date.now()+'_'+Math.random());await request('/api/member/promotions/create?profileId='+encodeURIComponent(state.profile.profile_id),{method:'POST',body:payload});msg('Draft created.','good')}resetForm();await loadWorkspace()})});
function renderItems(){list.replaceChildren();const mediaSelect=mediaForm.elements.promotionId;mediaSelect.replaceChildren();if(!state.items.length){list.textContent='No coupons, promotions or events yet. Use the form above to create your first draft.';mediaPanel.hidden=true;return}mediaPanel.hidden=false;state.items.forEach(item=>{const opt=document.createElement('option');opt.value=item.promotion_id;opt.textContent=labelKind(item.kind)+' — '+item.title;mediaSelect.append(opt);const card=document.createElement('article');card.className='r1365-item';const h=document.createElement('h3');h.textContent=item.title;const meta=document.createElement('div');meta.className='r1365-item-meta';meta.innerHTML=`<span>${labelKind(item.kind)}</span><span class="r1365-state">${item.state}</span>${item.end_at?`<span>Ends ${new Date(item.end_at).toLocaleString()}</span>`:''}`;const p=document.createElement('p');p.textContent=item.description;card.append(h,meta,p);if(item.promo_code){const c=document.createElement('p');c.textContent='Code: '+item.promo_code;card.append(c)}if(item.discount_text){const d=document.createElement('p');d.textContent=item.discount_text;card.append(d)}if(item.public_reason){const r=document.createElement('p');r.className='fine-print';r.textContent=item.public_reason;card.append(r)}const actions=document.createElement('div');actions.className='r1365-actions';if(!['SUBMITTED','PUBLISHED'].includes(item.state)){actions.append(btn('Edit',()=>editItem(item)))}if(['DRAFT','CHANGES_REQUESTED','UNPUBLISHED'].includes(item.state))actions.append(btn('Submit for review',()=>submitItem(item),true));if(item.state==='PUBLISHED')actions.append(btn('Unpublish',()=>postItem('/api/member/promotions/unpublish',item)));actions.append(btn('Remove',()=>removeItem(item)));const mediaBtn=btn('Add graphic / flyer',()=>{mediaSelect.value=item.promotion_id;mediaForm.scrollIntoView({behavior:'smooth',block:'start'})});actions.append(mediaBtn);card.append(actions);list.append(card)})}
function btn(text,fn,primary=false){const b=document.createElement('button');b.type='button';b.className='button'+(primary?' primary':'');b.textContent=text;b.addEventListener('click',()=>busy(fn));return b}
function editItem(item){state.editing=item;form.elements.kind.value=item.kind;form.elements.title.value=item.title||'';form.elements.description.value=item.description||'';form.elements.promoCode.value=item.promo_code||'';form.elements.discountText.value=item.discount_text||'';form.elements.actionUrl.value=item.action_url||'';form.elements.startAt.value=toLocal(item.start_at);form.elements.endAt.value=toLocal(item.end_at);form.elements.eventLocation.value=item.event_location||'';q('[data-r1365-save]').textContent='Save changes';editor.hidden=false;editor.scrollIntoView({behavior:'smooth',block:'start'})}
async function submitItem(item){await postItem('/api/member/promotions/submit',item,'Submitted for review.')}
async function postItem(path,item,success){await request(path+'?profileId='+encodeURIComponent(state.profile.profile_id),{method:'POST',body:{promotionId:item.promotion_id}});msg(success||'Saved.','good');await loadWorkspace()}
async function removeItem(item){if(!confirm('Remove this '+labelKind(item.kind).toLowerCase()+'?'))return;await postItem('/api/member/promotions/remove',item,'Item removed.')}
async function imageToWebp(file){let bitmap;try{bitmap=await createImageBitmap(file)}catch{throw new Error('Your browser could not prepare that image. Try a current browser or a WebP image.')}const scale=Math.min(1,3000/bitmap.width,3000/bitmap.height),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();for(const quality of [.9,.82,.74,.66,.58,.5]){const blob=await new Promise(r=>canvas.toBlob(r,'image/webp',quality));if(blob&&blob.size<=4*1024*1024)return blob}throw new Error('That image is still larger than 4 MB after preparation. Choose a smaller image.')}
mediaForm?.addEventListener('submit',e=>{e.preventDefault();busy(async()=>{const d=new FormData(mediaForm),file=d.get('file');if(!(file instanceof File)||!file.size)throw new Error('Choose an image.');if(!d.get('rights'))throw new Error('Confirm you have permission to publish this image.');const blob=await imageToWebp(file),profile=encodeURIComponent(state.profile.profile_id),promotionId=encodeURIComponent(d.get('promotionId')),mediaKind=encodeURIComponent(d.get('mediaKind'));const r=await fetch(API+`/api/member/promotions/media/upload?profileId=${profile}&promotionId=${promotionId}&mediaKind=${mediaKind}`,{method:'POST',credentials:'include',cache:'no-store',headers:{'Content-Type':'image/webp','X-Franklin-Rights-Confirmed':'true'},body:blob});let out={};try{out=await r.json()}catch{}if(!r.ok)throw new Error(out.message||out.error?.message||'The graphic could not be uploaded.');await request('/api/member/promotions/media/submit?profileId='+profile,{method:'POST',body:{promotionId:d.get('promotionId'),mediaId:out.mediaId}});mediaForm.reset();msg('Graphic uploaded and submitted for review.','good');await loadWorkspace()})});
function renderMedia(){mediaList.replaceChildren();if(!state.media.length){mediaList.textContent='No promotional graphics or flyers submitted yet.';return}state.media.forEach(m=>{const row=document.createElement('div');row.className='r1365-item-meta';row.textContent=`${String(m.media_kind||'').replaceAll('_',' ')} · ${m.state} · ${Math.round((m.byte_size||0)/1024)} KB`;mediaList.append(row)})}
busy(loadProfiles);
})();
